  3	predicate isPrefixPred(pre:string, str:string)
  4	{
  5		(|pre| <= |str|) && 
  6		pre == str[..|pre|]
  7	}
  8	
  9	predicate isNotPrefixPred(pre:string, str:string)
 10	{
 11		(|pre| > |str|) || 
 12		pre != str[..|pre|]
 13	}
 14	
 15	lemma PrefixNegationLemma(pre:string, str:string)
 16		ensures  isPrefixPred(pre,str) <==> !isNotPrefixPred(pre,str)
 17		ensures !isPrefixPred(pre,str) <==>  isNotPrefixPred(pre,str)
 18	{}
 19	
 20	method isPrefix(pre: string, str: string) returns (res:bool)
 21		ensures !res <==> isNotPrefixPred(pre,str)
 22		ensures  res <==> isPrefixPred(pre,str)
 23	{
 24		if |pre| > |str|
 25	    	{return false;}
 26	
 27	  	var i := 0;
 28	  	while i < |pre|
 29	    	decreases |pre| - i
 30	    	invariant 0 <= i <= |pre|
 31	    	invariant forall j :: 0 <= j < i ==> pre[j] == str[j]
 32	  	{
 33	    	if pre[i] != str[i]
 34	    	{
 35	       		return false;
 36	    	} 
 37	    	i := i + 1;
 38	  	}
 39	 	return true;
 40	}
 41	predicate isSubstringPred(sub:string, str:string)
 42	{
 43		(exists i :: 0 <= i <= |str| &&  isPrefixPred(sub, str[i..]))
 44	}
 45	
 46	predicate isNotSubstringPred(sub:string, str:string)
 47	{
 48		(forall i :: 0 <= i <= |str| ==> isNotPrefixPred(sub,str[i..]))
 49	}
 50	
 51	lemma SubstringNegationLemma(sub:string, str:string)
 52		ensures  isSubstringPred(sub,str) <==> !isNotSubstringPred(sub,str)
 53		ensures !isSubstringPred(sub,str) <==>  isNotSubstringPred(sub,str)
 54	{}
 55	
 56	method isSubstring(sub: string, str: string) returns (res:bool)
 57		ensures  res <==> isSubstringPred(sub, str)
 58		//ensures !res <==> isNotSubstringPred(sub, str) // This postcondition follows from the above lemma.
 59	{
 60		if |sub| > |str| {
 61	        return false;
 62	    }
 63	
 64	    var i := |str| - |sub|;
 65	    while i >= 0 
 66	    decreases i
 67	    invariant i >= -1
 68	    {
 69	        var isPref := isPrefix(sub, str[i..]);
 70	        if isPref
 71	        {
 72	            return true;
 73	        }
 74	        i := i-1;
 75	    }
 76	    return false;
 77	}
 78	
 79	predicate haveCommonKSubstringPred(k:nat, str1:string, str2:string)
 80	{
 81		exists i1, j1 :: 0 <= i1 <= |str1|- k && j1 == i1 + k && isSubstringPred(str1[i1..j1],str2)
 82	}
 83	
 84	predicate haveNotCommonKSubstringPred(k:nat, str1:string, str2:string)
 85	{
 86		forall i1, j1 :: 0 <= i1 <= |str1|- k && j1 == i1 + k ==>  isNotSubstringPred(str1[i1..j1],str2)
 87	}
 88	
 89	lemma commonKSubstringLemma(k:nat, str1:string, str2:string)
 90		ensures  haveCommonKSubstringPred(k,str1,str2) <==> !haveNotCommonKSubstringPred(k,str1,str2)
 91		ensures !haveCommonKSubstringPred(k,str1,str2) <==>  haveNotCommonKSubstringPred(k,str1,str2)
 92	{}
 93	
 94	method haveCommonKSubstring(k: nat, str1: string, str2: string) returns (found: bool)
 95		ensures found  <==>  haveCommonKSubstringPred(k,str1,str2)
 96		//ensures !found <==> haveNotCommonKSubstringPred(k,str1,str2) // This postcondition follows from the above lemma.
 97	{
 98		 if( |str1| < k || |str2| < k){
 99	        return false;
100	    }
101	    var i := |str1| - k;
102	    while i >= 0
103	      decreases i
104	      invariant i >= -1 
105	      invariant forall j,t :: i < j <= |str1| - k && t==j+k ==> !isSubstringPred(str1[j..t], str2)
106	    {
107					var t := i+k;
108	        var isSub := isSubstring(str1[i..t], str2);
109	        if isSub 
110	        {
111	            return true;
112	        }
113	        i := i-1;
114	    }
115	    return false;
116	}
117	
118	method maxCommonSubstringLength(str1: string, str2: string) returns (len:nat)
119		requires (|str1| <= |str2|)
120		ensures (forall k :: len < k <= |str1| ==> !haveCommonKSubstringPred(k,str1,str2))
121		ensures haveCommonKSubstringPred(len,str1,str2)
122	{
123		var i := |str1|;
124	
125	  	while i > 0
126	  	decreases i
127	  	invariant i >= 0
128	  	invariant forall j :: i < j <= |str1| ==> !haveCommonKSubstringPred(j, str1, str2)
129	  	{
130	    	var ans := haveCommonKSubstring(i, str1, str2);
131	    	if ans {
132	       		return i;
133	    	}
134	    	i := i -1;
135	  	}
136	  	assert i == 0;
137		assert isPrefixPred(str1[0..0],str2[0..]);
138	  	return 0;
139	}
